<section class="container page-section"><p class="breadcrumb"><a href="/">หน้าแรก</a> / <?= e($title) ?></p><div class="page-heading"><p class="eyebrow"><?= $type==='post'?'NEWS & UPDATES':'EVENTS & ACTIVITIES' ?></p><h1><?= e($title) ?></h1><p><?= $type==='post'?'ข่าวสารและความเคลื่อนไหวจากรั้วสวนดุสิต':'ติดตามกิจกรรมและพื้นที่แห่งการเรียนรู้' ?></p></div>
<?php if($type==='event'): ?><nav class="tabs"><?php foreach([''=>'กำลังจะมาถึง','past'=>'ย้อนหลัง'] as $key=>$label): ?><a class="<?= ($_GET['tab']??'')===$key?'selected':'' ?>" href="/events?<?= e(http_build_query(['tab'=>$key])) ?>"><?= $label ?></a><?php endforeach ?></nav><?php endif ?>
