<?php if($items): ?><div class="<?= $type==='post'?'news-grid':'event-list' ?>"><?php foreach($items as $card): if($type==='post'): require ROOT . '/views/partials/card.php'; else: ?><article class="event-card"><a href="<?= e(public_link($card)) ?>"><img src="<?= e(image_url($card['cover_id']?(int)$card['cover_id']:null)) ?>" alt="<?= e($card['title']) ?>" loading="lazy"></a><div><span class="badge <?= $card['event_status']==='cancelled'?'danger':'' ?>"><?= $card['event_status']==='cancelled'?'ยกเลิก':(!$card['starts_at']?'รอประกาศวันเวลา':($card['ends_at']<now()?'สิ้นสุดแล้ว':($card['starts_at']<=now()?'กำลังจัด':'กำลังจะมาถึง'))) ?></span><h2><a href="<?= e(public_link($card)) ?>"><?= e($card['title']) ?></a></h2><p><?= icon('calendar',17) ?> <?= e(thai_date($card['starts_at'])) ?></p><p><?= icon('pin',17) ?> <?= e($card['location']?:'สถานที่รอประกาศ') ?></p><a class="text-link" href="<?= e(public_link($card)) ?>">ดูรายละเอียด <?= icon('arrow',18) ?></a></div></article><?php endif; endforeach ?></div><?php pagination($count,$page); else: $emptyTitle='ไม่พบข้อมูลที่ตรงกับตัวกรอง'; $emptyLink=$type==='post'?'/news':'/events'; require ROOT . '/views/partials/empty.php'; endif ?></section>
